public void preTargetProcessing(DMFDefinitionGroupName      _definitionGroupName,
                                DMFExecutionId              _executionId,
                                DMFEntityName               _entityName,
                                OMGInboundMessageTable      _inboundMessage)
{
    // Create a new sales order, and populate SalesId on Staging table
    SalesTable      salesTable;
    CustTable       custTable = CustTable::find('004003');
    NumberSeq       numberSeq;
    ;

    ttsbegin;

    salesTable.clear();
    salesTable.initValue();

    numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesId());
    numberSeq.used();

    salesTable.SalesId          = numberSeq.num();
    salesTable.CustAccount      = custTable.AccountNum;
    salesTable.initFromCustTable();

    salesTable.InventSiteId = custTable.InventSiteId;
    salesTable.InventLocationId = custTable.InventLocation;

    salesTable.insert();

    // --------
    SalesOrderLineV2Staging     salesOrderLineV2Staging;

    while select forupdate salesOrderLineV2Staging
        where salesOrderLineV2Staging.DefinitionGroup   == _definitionGroupName   &&
              salesOrderLineV2Staging.ExecutionId       == _executionId
    {
        salesOrderLineV2Staging.SalesOrderNumber = salesTable.SalesId;
        salesOrderLineV2Staging.update();
    }

    ttscommit;
}

